mapper.select:
SELECT t.PADDING_CODE, MAX(t.SCHEDULE_DATE) AS LAST_DATE FROM ( SELECT PADDING_CODE, SCHEDULE_DATE FROM T_DJ_SCHEDULE_RESULT WHERE FACTORY_CODE = #{factoryCode} AND PADDING_CODE IN
#{code}
AND (CLASS1_PLAN_QTY IS NOT NULL AND CLASS1_PLAN_QTY > 0 OR CLASS2_PLAN_QTY IS NOT NULL AND CLASS2_PLAN_QTY > 0 OR CLASS3_PLAN_QTY IS NOT NULL AND CLASS3_PLAN_QTY > 0 OR CLASS4_PLAN_QTY IS NOT NULL AND CLASS4_PLAN_QTY > 0 OR CLASS5_PLAN_QTY IS NOT NULL AND CLASS5_PLAN_QTY > 0 OR CLASS6_PLAN_QTY IS NOT NULL AND CLASS6_PLAN_QTY > 0) UNION ALL SELECT PADDING_CODE, SCHEDULE_DATE FROM T_DJ_SCHEDULE_RESULT_LOG WHERE FACTORY_CODE = #{factoryCode} AND PADDING_CODE IN
#{code}
AND (CLASS1_PLAN_QTY IS NOT NULL AND CLASS1_PLAN_QTY > 0 OR CLASS2_PLAN_QTY IS NOT NULL AND CLASS2_PLAN_QTY > 0 OR CLASS3_PLAN_QTY IS NOT NULL AND CLASS3_PLAN_QTY > 0 OR CLASS4_PLAN_QTY IS NOT NULL AND CLASS4_PLAN_QTY > 0 OR CLASS5_PLAN_QTY IS NOT NULL AND CLASS5_PLAN_QTY > 0 OR CLASS6_PLAN_QTY IS NOT NULL AND CLASS6_PLAN_QTY > 0) ) t GROUP BY t.PADDING_CODE
